// config-anonymizer-i18n.js — 去識別化頁的 esc() 與語言字串 LANG（RV17-B 從 config-anonymizer.html 拆出，內容未改）
// 2026-08-09 稽核修復：原本未跳脫雙引號，但被用在 title="${esc(f.name)}" 這類雙引號屬性內
// （f.name 來自使用者上傳的 File.name，檔案系統/拖放完全可控），惡意檔名可提前結束屬性、
// 注入事件處理器（如 onmouseover=），構成儲存型 XSS；補上雙引號跳脫
const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
// ============================================================
// [I18N] 多語言支援
// ============================================================
